SELECT * FROM usuarios ORDER BY nombre ASC;

-- Con LIMIT para paginación
SELECT * FROM posts ORDER BY fecha_publicacion DESC LIMIT 10;
SELECT * FROM posts ORDER BY fecha_publicacion DESC LIMIT 10 OFFSET 10;
```

