### CREATE - Insertar Datos
```php
<?php
function crearUsuario($nombre, $email, $password) {
    $conexion = conectarDB();

    // Hash de contraseña
    $passwordHash = password_hash($password, PASSWORD_DEFAULT);

    // Preparar consulta
    $sql = "INSERT INTO usuarios (nombre, email, password) VALUES (?, ?, ?)";
    $stmt = $conexion->prepare($sql);

    if ($stmt === false) {
        die("Error en la consulta: " . $conexion->error);
    }

    // Vincular parámetros
    $stmt->bind_param("sss", $nombre, $email, $passwordHash);

    // Ejecutar
    $resultado = $stmt->execute();

    // Cerrar statement y conexión
    $stmt->close();
    $conexion->close();

    return $resultado;
}

// Uso
if ($_POST) {
    $exito = crearUsuario($_POST['nombre'], $_POST['email'], $_POST['password']);
    if ($exito) {
        echo "Usuario creado exitosamente";
    } else {
        echo "Error al crear usuario";
    }
}
?>
```

### READ - Leer Datos
```php
<?php
function obtenerUsuarios() {
    $conexion = conectarDB();

    $sql = "SELECT id, nombre, email, fecha_creacion FROM usuarios ORDER BY fecha_creacion DESC";
    $resultado = $conexion->query($sql);

    $usuarios = [];

    if ($resultado && $resultado->num_rows > 0) {
        while ($fila = $resultado->fetch_assoc()) {
            $usuarios[] = $fila;
        }
    }

    $conexion->close();
    return $usuarios;
}

function obtenerUsuarioPorId($id) {
    $conexion = conectarDB();

    $sql = "SELECT id, nombre, email, fecha_creacion FROM usuarios WHERE id = ?";
    $stmt = $conexion->prepare($sql);
    $stmt->bind_param("i", $id);
    $stmt->execute();

    $resultado = $stmt->get_result();
    $usuario = $resultado->fetch_assoc();

    $stmt->close();
    $conexion->close();

    return $usuario;
}

// Uso
$usuarios = obtenerUsuarios();
foreach ($usuarios as $usuario) {
    echo "Nombre: " . $usuario['nombre'] . "<br>";
    echo "Email: " . $usuario['email'] . "<br><br>";
}
?>
```

