### Modelo para Posts
```php
<?php
// models/Post.php
class Post {
    public static function obtenerTodos($limite = 10, $offset = 0, $soloPublicados = true) {
        $conexion = conectarDB();

        $where = $soloPublicados ? "WHERE p.estado = 'publicado'" : "";

        $sql = "SELECT 
                    p.*, 
                    u.nombre as autor_nombre,
                    u.email as autor_email,
                    c.nombre as categoria_nombre,
                    c.slug as categoria_slug,
                    c.color as categoria_color
                FROM posts p
                LEFT JOIN usuarios u ON p.usuario_id = u.id
                LEFT JOIN categorias c ON p.categoria_id = c.id
                $where
                ORDER BY p.fecha_publicacion DESC
                LIMIT ? OFFSET ?";

        $stmt = $conexion->prepare($sql);
        $stmt->bind_param("ii", $limite, $offset);
        $stmt->execute();
        $resultado = $stmt->get_result();

        $posts = [];
        while ($fila = $resultado->fetch_assoc()) {
            $posts[] = $fila;
        }

        $stmt->close();
        $conexion->close();

        return $posts;
    }

    public static function obtenerPorSlug($slug) {
        $conexion = conectarDB();

        $sql = "SELECT 
                    p.*, 
                    u.nombre as autor_nombre,
                    u.email as autor_email,
                    u.biografia as autor_biografia,
                    u.avatar as autor_avatar,
                    c.nombre as categoria_nombre,
                    c.slug as categoria_slug,
                    c.color as categoria_color
                FROM posts p
                LEFT JOIN usuarios u ON p.usuario_id = u.id
                LEFT JOIN categorias c ON p.categoria_id = c.id
                WHERE p.slug = ? AND p.estado = 'publicado'";

        $stmt = $conexion->prepare($sql);
        $stmt->bind_param("s", $slug);
        $stmt->execute();
        $resultado = $stmt->get_result();
        $post = $resultado->fetch_assoc();

        $stmt->close();
        $conexion->close();

        return $post;
    }

    public static function obtenerPorCategoria($categoriaSlug, $limite = 10, $offset = 0) {
        $conexion = conectarDB();

        $sql = "SELECT 
                    p.*, 
                    u.nombre as autor_nombre,
                    u.email as autor_email,
                    c.nombre as categoria_nombre,
                    c.slug as categoria_slug,
                    c.color as categoria_color
                FROM posts p
                LEFT JOIN usuarios u ON p.usuario_id = u.id
                LEFT JOIN categorias c ON p.categoria_id = c.id
                WHERE c.slug = ? AND p.estado = 'publicado'
                ORDER BY p.fecha_publicacion DESC
                LIMIT ? OFFSET ?";

        $stmt = $conexion->prepare($sql);
        $stmt->bind_param("sii", $categoriaSlug, $limite, $offset);
        $stmt->execute();
        $resultado = $stmt->get_result();

        $posts = [];
        while ($fila = $resultado->fetch_assoc()) {
            $posts[] = $fila;
        }

        $stmt->close();
        $conexion->close();

        return $posts;
    }

    public static function crear($datos) {
        $conexion = conectarDB();

        $sql = "INSERT INTO posts (titulo, slug, contenido, extracto, usuario_id, categoria_id, estado, fecha_publicacion) 
                VALUES (?, ?, ?, ?, ?, ?, ?, ?)";

        $stmt = $conexion->prepare($sql);
        $fechaPublicacion = $datos['estado'] === 'publicado' ? date('Y-m-d H:i:s') : null;

        $stmt->bind_param("ssssiiss", 
            $datos['titulo'],
            $datos['slug'],
            $datos['contenido'],
            $datos['extracto'],
            $datos['usuario_id'],
            $datos['categoria_id'],
            $datos['estado'],
            $fechaPublicacion
        );

        $resultado = $stmt->execute();
        $idInsertado = $conexion->insert_id;

        $stmt->close();
        $conexion->close();

        return $resultado ? $idInsertado : false;
    }

    public static function incrementarVisitas($postId) {
        $conexion = conectarDB();

        $sql = "UPDATE posts SET visitas = visitas + 1 WHERE id = ?";
        $stmt = $conexion->prepare($sql);
        $stmt->bind_param("i", $postId);
        $stmt->execute();
        $stmt->close();
        $conexion->close();
    }

    public static function buscar($termino, $limite = 10, $offset = 0) {
        $conexion = conectarDB();

        $termino = "%$termino%";
        $sql = "SELECT 
                    p.*, 
                    u.nombre as autor_nombre,
                    c.nombre as categoria_nombre
                FROM posts p
                LEFT JOIN usuarios u ON p.usuario_id = u.id
                LEFT JOIN categorias c ON p.categoria_id = c.id
                WHERE (p.titulo LIKE ? OR p.contenido LIKE ? OR p.extracto LIKE ?) 
                AND p.estado = 'publicado'
                ORDER BY p.fecha_publicacion DESC
                LIMIT ? OFFSET ?";

        $stmt = $conexion->prepare($sql);
        $stmt->bind_param("sssii", $termino, $termino, $termino, $limite, $offset);
        $stmt->execute();
        $resultado = $stmt->get_result();

        $posts = [];
        while ($fila = $resultado->fetch_assoc()) {
            $posts[] = $fila;
        }

        $stmt->close();
        $conexion->close();

        return $posts;
    }
}
