### Script de Backup de Base de Datos
```php
<?php
// admin/backup.php
require_once '../config/database.php';
require_once '../auth.php';
requiereRol('admin');

if ($_SERVER['REQUEST_METHOD'] === 'POST' && isset($_POST['crear_backup'])) {
    $conexion = conectarDB();

    // Nombre del archivo de backup
    $fecha = date('Y-m-d_H-i-s');
    $archivo_backup = "backup_{$fecha}.sql";
    $ruta_backup = __DIR__ . "/../backups/{$archivo_backup}";

    // Crear directorio de backups si no existe
    if (!is_dir(__DIR__ . '/../backups')) {
        mkdir(__DIR__ . '/../backups', 0755, true);
    }

    // Obtener todas las tablas
    $tablas = [];
    $resultado = $conexion->query("SHOW TABLES");
    while ($fila = $resultado->fetch_array()) {
        $tablas[] = $fila[0];
    }

    $sql_backup = "";

    // Recorrer cada tabla
    foreach ($tablas as $tabla) {
        // Obtener estructura de la tabla
        $resultado = $conexion->query("SHOW CREATE TABLE {$tabla}");
        $fila = $resultado->fetch_array();
        $sql_backup .= "\n\n-- Estructura de la tabla {$tabla}\n";
        $sql_backup .= $fila[1] . ";\n\n";

        // Obtener datos de la tabla
        $resultado = $conexion->query("SELECT * FROM {$tabla}");

        while ($fila = $resultado->fetch_assoc()) {
            $sql_backup .= "INSERT INTO {$tabla} VALUES(";

            $valores = [];
            foreach ($fila as $valor) {
                $valor = $conexion->real_escape_string($valor);
                $valores[] = "'{$valor}'";
            }

            $sql_backup .= implode(",", $valores) . ");\n";
        }
    }

    // Guardar archivo
    if (file_put_contents($ruta_backup, $sql_backup)) {
        $_SESSION['mensaje'] = "Backup creado exitosamente: {$archivo_backup}";
    } else {
        $_SESSION['error'] = "Error al crear el backup";
    }

    $conexion->close();
    header("Location: backup.php");
    exit;
}

// Listar backups existentes
$backups = [];
if (is_dir(__DIR__ . '/../backups')) {
    $archivos = scandir(__DIR__ . '/../backups');
    foreach ($archivos as $archivo) {
        if (pathinfo($archivo, PATHINFO_EXTENSION) === 'sql') {
            $ruta = __DIR__ . "/../backups/{$archivo}";
            $backups[] = [
                'nombre' => $archivo,
                'tamaño' => filesize($ruta),
                'fecha' => filemtime($ruta)
            ];
        }
    }

    // Ordenar por fecha (más reciente primero)
    usort($backups, function($a, $b) {
        return $b['fecha'] - $a['fecha'];
    });
}
