        ];
        $estado['status'] = 'error';
    }

    $conexion->close();
} catch (Exception $e) {
    $estado['checks']['database'] = [
        'status' => 'error',
        'message' => $e->getMessage()
    ];
    $estado['status'] = 'error';
}

// Verificar directorios de uploads
$directorios = ['uploads', 'uploads/images', 'uploads/avatars', 'backups'];
foreach ($directorios as $directorio) {
    $ruta = __DIR__ . "/{$directorio}";

    if (!is_dir($ruta)) {
        $estado['checks']["directory_{$directorio}"] = [
            'status' => 'error',
            'message' => "Directorio {$directorio} no existe"
        ];
        $estado['status'] = 'error';
    } elseif (!is_writable($ruta)) {
        $estado['checks']["directory_{$directorio}"] = [
            'status' => 'warning',
            'message' => "Directorio {$directorio} no tiene permisos de escritura"
        ];
    } else {
        $estado['checks']["directory_{$directorio}"] = [
            'status' => 'ok',
            'message' => "Directorio {$directorio} accesible"
        ];
    }
}

// Verificar uso de disco
$usoDisco = disk_free_space(__DIR__);
$totalDisco = disk_total_space(__DIR__);
$porcentajeUso = (1 - ($usoDisco / $totalDisco)) * 100;

$estado['disk_usage'] = [
    'free' => round($usoDisco / (1024 * 1024 * 1024), 2) . ' GB',
    'total' => round($totalDisco / (1024 * 1024 * 1024), 2) . ' GB',
    'usage_percent' => round($porcentajeUso, 2)
];

if ($porcentajeUso > 90) {
    $estado['checks']['disk_space'] = [
        'status' => 'error',
        'message' => 'Espacio en disco crítico'
    ];
    $estado['status'] = 'error';
} elseif ($porcentajeUso > 80) {
    $estado['checks']['disk_space'] = [
        'status' => 'warning',
        'message' => 'Espacio en disco bajo'
    ];
}

// Verificar versión de PHP
$phpVersion = phpversion();
$estado['php_version'] = $phpVersion;

if (version_compare($phpVersion, '7.4.0', '<')) {
    $estado['checks']['php_version'] = [
        'status' => 'warning',
        'message' => 'Versión de PHP antigua'
    ];
}

echo json_encode($estado, JSON_PRETTY_PRINT);
